#!/usr/bin/env python3
"""Turn a motion generated by NVIDIA Kimodo into a clip the swordsman can play.

    python3 tools/kimodo_import.py motion.npz studio/motions/walk.json [--meta meta.json]

Kimodo's NPZ holds, per frame, each joint's position (`posed_joints`, [T, J, 3]) and world rotation (`global_rot_mats`,
[T, J, 3, 3]) on the SOMA skeleton, at 30 frames a second, in metres, Y up, the figure facing +Z. Its rotations are measured
from a T-pose with every joint at the identity, which is exactly how src/rig/skeleton.mjs lays the swordsman out, so a joint's
rotation carries over unchanged and only two things are worked out here: each joint's rotation against its own parent in
*our* hierarchy (we leave out Neck2, the jaw, eyes and finger ends), and the hips' travel scaled to our shorter legs.
The 77-joint SOMA skeleton is accepted too: the joints are looked up by name.
"""
import argparse
import json
import sys

import numpy as np

# SOMASkeleton30 in Kimodo's order (kimodo/skeleton/definitions.py)
SOMA30 = ["Hips", "Spine1", "Spine2", "Chest", "Neck1", "Neck2", "Head", "Jaw", "LeftEye", "RightEye", "LeftShoulder",
          "LeftArm", "LeftForeArm", "LeftHand", "LeftHandThumbEnd", "LeftHandMiddleEnd", "RightShoulder", "RightArm",
          "RightForeArm", "RightHand", "RightHandThumbEnd", "RightHandMiddleEnd", "LeftLeg", "LeftShin", "LeftFoot",
          "LeftToeBase", "RightLeg", "RightShin", "RightFoot", "RightToeBase"]
# ours: joint -> parent, parents first (src/rig/skeleton.mjs, without the sword, which rides the hand)
OURS = [("Hips", None), ("Spine1", "Hips"), ("Spine2", "Spine1"), ("Chest", "Spine2"), ("Neck1", "Chest"), ("Head", "Neck1"),
        ("LeftShoulder", "Chest"), ("RightShoulder", "Chest"), ("LeftArm", "LeftShoulder"), ("RightArm", "RightShoulder"),
        ("LeftForeArm", "LeftArm"), ("RightForeArm", "RightArm"), ("LeftHand", "LeftForeArm"), ("RightHand", "RightForeArm"),
        ("LeftLeg", "Hips"), ("RightLeg", "Hips"), ("LeftShin", "LeftLeg"), ("RightShin", "RightLeg"),
        ("LeftFoot", "LeftShin"), ("RightFoot", "RightShin"), ("LeftToeBase", "LeftFoot"), ("RightToeBase", "RightFoot")]
OUR_LEG = 0.40 + 0.41  # thigh + shin, metres
OUR_HIPS = [0.0, 0.93, 0.0]


def quaternion(m):
    """Rotation matrices [..., 3, 3] -> quaternions [..., 4] as x, y, z, w."""
    m = np.asarray(m, dtype=np.float64)
    w = np.sqrt(np.maximum(0, 1 + m[..., 0, 0] + m[..., 1, 1] + m[..., 2, 2])) / 2
    x = np.sqrt(np.maximum(0, 1 + m[..., 0, 0] - m[..., 1, 1] - m[..., 2, 2])) / 2
    y = np.sqrt(np.maximum(0, 1 - m[..., 0, 0] + m[..., 1, 1] - m[..., 2, 2])) / 2
    z = np.sqrt(np.maximum(0, 1 - m[..., 0, 0] - m[..., 1, 1] + m[..., 2, 2])) / 2
    x = np.copysign(x, m[..., 2, 1] - m[..., 1, 2])
    y = np.copysign(y, m[..., 0, 2] - m[..., 2, 0])
    z = np.copysign(z, m[..., 1, 0] - m[..., 0, 1])
    q = np.stack([x, y, z, w], axis=-1)
    return q / np.linalg.norm(q, axis=-1, keepdims=True)


def convert(npz, names=None):
    joints, world = npz["posed_joints"], npz["global_rot_mats"]
    if joints.ndim == 4:  # several samples: take the first
        joints, world = joints[0], world[0]
    names = names or (SOMA30 if joints.shape[1] == 30 else None)
    if names is None:
        raise SystemExit(f"{joints.shape[1]} joints: pass the joint names with --names (a JSON list, in the file's order)")
    index = {name: i for i, name in enumerate(names)}
    missing = [name for name, _ in OURS if name not in index]
    if missing:
        raise SystemExit("The motion has no joint called " + ", ".join(missing))
    local = []
    for name, parent in OURS:
        g = world[:, index[name]]
        local.append(g if parent is None else np.einsum("tji,tjk->tik", world[:, index[parent]], g))
    # how long their legs are, read from the motion itself, sets how far our hips travel
    leg = (np.linalg.norm(joints[:, index["LeftShin"]] - joints[:, index["LeftLeg"]], axis=-1).mean()
           + np.linalg.norm(joints[:, index["LeftFoot"]] - joints[:, index["LeftShin"]], axis=-1).mean())
    scale = OUR_LEG / leg
    hips = joints[:, index["Hips"]].astype(np.float64) * scale
    hips[:, [0, 2]] -= hips[0, [0, 2]]  # start over the origin
    root = hips - np.array(OUR_HIPS)
    return {
        "fps": 30,
        "frames": int(joints.shape[0]),
        "scale": round(float(scale), 4),
        "joints": [name for name, _ in OURS],
        "root": np.round(root, 4).tolist(),
        "rot": np.round(quaternion(np.stack(local, axis=1)), 4).tolist(),
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("npz")
    parser.add_argument("out")
    parser.add_argument("--meta", help="the meta.json Kimodo saved beside the motion: its prompt is kept with the clip")
    parser.add_argument("--names", help="JSON list of joint names, for a skeleton other than SOMA-30")
    args = parser.parse_args()
    clip = convert(np.load(args.npz), json.loads(args.names) if args.names else None)
    if args.meta:
        clip["text"] = json.load(open(args.meta)).get("text")
    with open(args.out, "w") as f:
        json.dump(clip, f, separators=(",", ":"))
    print(f"{args.out}: {clip['frames']} frames ({clip['frames'] / clip['fps']:.2f} s), legs scaled x{clip['scale']}", file=sys.stderr)


if __name__ == "__main__":
    main()
